INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Social workers and activists tell of Sr. Stan’s influence on them', 'social-workers-and-activists-tell-of-late-sr-stans-influence-on-them', '<p>Writing on rip.ie, a woman who just signed herself as <strong>Ruth</strong>, said that Sr. Stan had greatly influenced her career:</p>
<blockquote><p>“I was lucky enough to meet Sr. Stan a few times during the period I worked in Focus Ireland. I can say with certainty that she has been an inspiration to me throughout my career in Focus and moving into social work. She was a special woman who has left a positive mark on Dublin and the people she met.”</p></blockquote>
<p><strong>Deirdre Clancy</strong> wrote that her example had been an inspiration:</p>
<blockquote><p>“Stan stepped up to offer help to an activist group I was involved with many years ago, when we took a stand against the Iraq War. She provided accommodation to a member of the group from abroad who needed somewhere to stay while on bail. Her kindness on that occasion to a group that was under pressure, often dealing with chaotic circumstances, while she was already helping the needy on a daily basis, struck me as extraordinary.”</p></blockquote>
<p><figure aria-describedby="caption-attachment-255731"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others.jpg" alt="" width="2048" height="2048" srcset="https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-300x300.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-1024x1024.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-150x150.jpg 150w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-768x768.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-1536x1536.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-1080x1080.jpg 1080w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-440x440.jpg 440w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-24x24.jpg 24w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-48x48.jpg 48w, https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stan-said-that-compassion-is-a-choice-we-make-to-act-in-the-service-of-others-96x96.jpg 96w" sizes="(max-width: 2048px) 100vw, 2048px" /><figcaption><em>• Sr Stan founded Focus Ireland in the 1980s and always emphasised the importance of involving people who are homeless, or have been directly affected by homelessness, in the development of homelessness services in Ireland.</em></figcaption></figure></p>
<p><strong>Social worker turned broadcaster Joe Duffy</strong>, also writing on rip.ie, said Sr. Stan had changed his life when he was a young man at risk of missing out:</p>
<blockquote><p>“1980… Expelled from TCD, I needed one placement to complete a social work degree! Everyone ran a mile except Stan in Kilkenny. We’ve always kept in touch &#8211; her mischievous sense of humour to the fore.”</p></blockquote>
<p>Another person who just used her first name, <strong>Aoife</strong>, said that Sr. Stan had been “the key influence in my career choice as a social worker”.</p>
<blockquote><p>“Thank you for providing me with the opportunity to learn and educate myself about the challenges that people face in life and how to support them through those difficult times without judgement or prejudice.</p>
<p>“Even as the life founder of the organisation, you cleared dishes and cleaned tables in the coffee shop, chatting with customers and staff each week. You were so genuine, humble and unassuming, with time for everyone,” she wrote.</p></blockquote>
<p><strong>Longford teacher Mary Killian</strong> stated that she had a massive impact on young people:</p>
<blockquote><p>“What an incredible person she was. I was so lucky to meet Sr. Stan and Rachel Collier many times through the marvellous &#8216;Young Social Innovators&#8217; initiative for young people that they established. ‘Be the change you want to see in the world’ Sr. Stan used to say and through the YSI she encouraged our students to engage with that belief. As a result, we embarked on so many wonderful, exciting and important projects from fundraising for our school defibrillator, setting up a Health Week in our school and establishing so many links with our wider community e.g. older people in residential homes, Autistic Centres, Developing Country charities, Mental health bodies etc,” she wrote.</p></blockquote>
<p><strong>Pauline</strong>, who wrote that she is married to a woman called Brenda, and is a former Focus Ireland worker, praised her example:</p>
<blockquote><p>“Stan, what an inspirational lady you were. So unassuming, modest, but so brave in fighting injustice and the systems that were the cause of injustice. A lady before her time and putting her head above the parapet when it came to marriage equality and was so kind in writing a piece for our wedding in 2017. I will be forever grateful to have worked with you and I learned so much from you. Rest in peace.”</p></blockquote>', 'The death of Sister Stanislaus Kennedy led to many tributes and stories being told by social workers, activists and teachers who were influenced by her bravery, modesty and determination to fight systems that led to injustice.', 'https://changingireland.ie/wp-content/uploads/2025/11/Sr-Stanislaus-Kennedy-founded-Focus-Ireland-following-her-research-into-the-needs-of-women-experiencing-homelessness-in-Dublin-in-the-1980s.png', '', '[{"slug":"people","title":"People"}]', '[{"slug":"activism","title":"activism"},{"slug":"funeral","title":"funeral"},{"slug":"joe-duffy","title":"Joe Duffy"},{"slug":"sister-stan","title":"Sister Stan"},{"slug":"social-work","title":"social work"},{"slug":"stanislaus-kennedy","title":"Stanislaus Kennedy"}]', '', 255693, 1, '2025-11-18T02:21:11Z', '2025-11-18T02:55:48Z', '2025-11-18T02:21:11Z')
