INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('EU backs Kildare communities to show it how integration works best', 'eu-backs-kildare-communities-to-show-it-how-integration-works', '<p>Co.Here (officially titled Community Connect under the EU’s Social Innovation+ programme) will build on three years of lived community experience from Helping Irish Hosts, evidence-based research from UCD, and ethical technology from international partner Pairity.</p>
<p>Together with refugees and local communities, the partners will develop and test a new path to meaningful and mutually beneficial integration.</p>
<p>The project will run for one year across Maynooth, Kilcock, Leixlip, Celbridge, and Straffan, gathering evidence to inform local authority practice and national policy on refugee integration.</p>
<p>“Welcoming newcomers brings real opportunities, but it also creates challenges for communities under pressure,” said Dr. Graham Finlay, Research Lead at UCD. “With Co.Here we want to understand, through evidence, how communities and newcomers can find common ground and build the kind of belonging that lasts.”</p>
<p>Jill Robinson is a co-founder of Helping Irish Hosts, which was established when huge numbers of Ukrainians were coming to Ireland in the early months of the Russian invasion.</p>
<p>Speaking about the project, she said, “At its heart, Co.Here is about joining the dots between real people and real experiences. It builds on lived community experience and applies technology to make those efforts more practical, connected, and lasting, for everyone involved.”</p>
<p>Welcoming the launch Kildare county councillor Angela Feeney said said it was &#8220;such a positive initiative&#8221; to explore practical, real-life approaches to integration.</p>
<p>&#8220;It’s a model of good practice, taking a partnership approach to solving everyday problems. At its core is listening to lived experience, looking at what is already in place in our communities, and using technology to help communities and newcomers connect. It is by working together that we achieve more. Ní neart go cur le chéile.”</p>
<p>Over the coming year, Co.Here will invite Ukrainian newcomers, local residents, community groups, and employers in North Kildare to take part. Participants will be matched with opportunities in learning, work, education, health, and social life, while also sharing their insights on what helps people feel at home. By gathering this evidence, the pilot project aims not only to improve support locally, but also to inform integration policy and practice nationally.</p>
<p>People in North Kildare are invited to join the pilot project, including:</p>
<ul>
<li>Refugees (aka Ukrainian Beneficiaries of Temporary Protection).</li>
<li>Local residents and host families (past and present).</li>
<li>Employers, clubs and community groups.</li>
</ul>
<p>To find out more: <a href="https://www.helpingirishhosts.com/co-here">https://www.helpingirishhosts.com/co-here</a></p>
<p>To get involved or share your experiences, email: <a href="mailto:maryna@helpingirishhosts.com">maryna@helpingirishhosts.com </a></p>', 'In early October, a new EU-funded pilot project was launched in North Kildare, bringing together local communities, employers, and Ukrainian refugees. It is the only Irish project selected for this Europe-wide programme, which aims to explore practical approaches to refugee integration.', 'https://changingireland.ie/wp-content/uploads/2025/10/Jill-Robinson-Co-Founder-of-HIH-Clrr-Angela-Feeney-Jennifer-Luke-Community-Liaison-HIH-scaled-e1761166729714.jpg', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[{"slug":"co-here","title":"Co.Here"},{"slug":"helping-irish-hosts","title":"Helping Irish Hosts"},{"slug":"integration","title":"integration"},{"slug":"kildare","title":"Kildare"}]', '', 255574, 1, '2025-11-16T08:01:45Z', '2025-11-18T05:20:24Z', '2025-11-16T08:01:45Z')
