INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Minister and officials hear ideas and concerns from communities nationwide', 'ministers-and-officials-hear-ideas-and-concerns-from-communities-nationwide', '<p><strong>Cllr. Fergal Dennehy, </strong><strong>Lord Mayor</strong><strong> of Cork, </strong>welcomed attendees to Millennium Hall, and appealed to Minister Buttimer to consider the challenges facing community organisations that are struggling to fill Community Employment vacancies. He said “the reality on the ground” was that “it is difficult today for community and voluntary organisations”.</p>
<p>Later, when we interviewed the Mayor, he called for incentives to encourage more people to take up CE posts and for more directly funded community workers.</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7098-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /></p>
<p>Opening the forum, <strong>Minister Buttimer </strong>welcomed all – in harsh weather conditions – on behalf of the Department of Rural and Community Development and the Gaeltacht.</p>
<p>He said the Department had begun work on developing a successor strategy for the community and volunteer sector as well as a new volunteering strategy.</p>
<p>“Each one is being developed in collaboration with the sector and other government departments, and will have the values and principles (for collaboration and partnership) rooted in their core,” he said.</p>
<p>He promised to pass on the Lord Mayor’s concerns over Community Employment to Minister Dara Calleary.</p>
<p><strong>The forum featured </strong>presentations on best practice from across the country and gave people a platform to speak about poverty and marginalisation. In that regard, there were alarming statistics regarding food poverty presented by representatives from a project in Cherry Orchard in Dublin.</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-scaled.jpg" alt="" width="2560" height="2036" srcset="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-300x239.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-1024x814.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-768x611.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-1536x1221.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-2048x1628.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7170-1080x859.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /></p>
<p><strong>Anne Fitzgerald</strong>, CEO of the <strong>Liffey Partnership</strong>, and <strong>Trisha Loughman</strong>, senior health promotion officer with the HSE, pointed to their recently published report called &#8220;Spinning Plates&#8221; which found that 43% residents in these parts of Dublin experience food poverty, compared to a national (also alarming) figure of 9%. For residents in Cherry Orchard there are 17 takeaways within a 1km range – which impacts on people’s health and pocket.</p>
<p>In regards to all anti-poverty work, Ann stressed that “It is really important to keep community voices at the heart” of discussions on policy. While noting the increasing number of foodbanks in Ireland, she welcomed the fact that there is now more focus and discussion on poverty than before.</p>
<p>In further presentations,  <strong>James O&#8217;Brien</strong><strong>, a volunteer from Wicklow, Laura O’Callaghan</strong> of the <strong>Disability Federation of Ireland</strong> and <strong>Michael Nicholson</strong> <strong>from Wicklow County Council</strong> shared insights from their <strong>Disability and Inclusion Steering Committe</strong><strong>e.</strong></p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7310-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /></p>
<p><strong>Collette Deeney</strong>, co-ordinator of <strong>Monaghan Children and Young People’s Services Committee</strong>, and <strong>Packie Kelly</strong>, manager of <strong>Teach na Daoine Family Resource Centre</strong>, delivered a presentation on <strong>Local Area Child Poverty Action Plan Pilots</strong>.</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/11/IMG_7344-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /></p>
<p>The afternoon featured presentations on the <em>We Act Campaign</em> by <strong>Claire McGowran</strong> and on <em>Public Consultation Guidelines</em> by <strong>Barry Vaughan</strong> from the Department of the Taoiseach.</p>
<p>In his closing remarks, <strong>Minister Buttimer</strong> thanked participants for their continued commitment to strengthening communities across Ireland.</p>
<p>“You are at the coalface and without you there would be catastrophe in my opinion,” he said. He noted concerns that “poverty is alive and well” and we must tap into the power of collaboration to tackle poverty.</p>
<p><em>As in previous years, for those who missed the forum, the views, proposals and presentation notes are expected to be made available in due course on gov.ie</em></p>', 'Cork today hosted the fourth annual National Civic Forum, marking the first time it was hosted outside Dublin. Opened by Corkonian and Minister of State, Jerry Buttimer, it brought together representatives from community organisations, agencies and local and central government to discuss how to tackle social exclusion and improve civic engagement and true collaboration.', 'https://changingireland.ie/wp-content/uploads/2025/11/IMG_7316-scaled.jpg', '', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"community-work-ireland","title":"Community Work Ireland"},{"slug":"department-of-rural-and-community-development-and-the-gaeltacht","title":"Department of Rural and Community Development and the Gaeltacht"},{"slug":"disability-federation-of-ireland-dfi","title":"Disability Federation of Ireland (DFI)"},{"slug":"liffey-partnership","title":"Liffey Partnership"},{"slug":"minister-of-state-jerry-buttimer","title":"Minister of State Jerry Buttimer"},{"slug":"wicklow-county-council","title":"Wicklow County Council"}]', '', 255705, 1, '2025-11-14T15:16:18Z', '2025-12-22T16:24:13Z', '2025-11-14T15:16:18Z')
