INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Minister Buttimer appalled by Gaza deaths and concerned for Irish volunteers in Israeli custody', 'minister-buttimer-appalled-by-gaza-deaths-and-concerned-for-irish-volunteers-in-israeli-custody', '<p>He told Changing Ireland:</p>
<p>“All of us abhor what has happened. The interception of the flotilla is wrong on a huge number of levels, in particular when you speak about someone like Sarah Clancy, Tadgh Hickey and others who are volunteering in their spare time in inverted commas to continue the work they are doing in terms of community work, intervening on behalf of people who are under on the margins now and who are being killed in what is an extraordinarily awful situation.</p>
<p>“So, as you know, government, through the Office of An Tánaiste and An Taoiseach are monitoring the situation, have engaged with the Irish Ambassador and the consular service available to people. We must uphold international law and that applies to Israel, it applies to all of us, they are not doing that,&#8221; he said.</p>
<div><iframe title="Minister Buttimer appalled by Gaza deaths and concerned for Irish volunteers in Israeli custody" width="696" height="392" src="https://www.youtube.com/embed/1Fv6G3PKS0A?feature=oembed&#038;enablejsapi=1" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>
<p>“And as a minister in the government, as an Irish citizen, I am concerned about fellow citizens, but equally as important, the people of Gaza. And we have as a government got to stand up for people. We have done that with the people of Palestine, in this case, An Taoiseach and An Tánaiste are monitoring on behalf of the government and we will do everything we can to ensure that our people are looked after and minded and they are not treated badly and shouldn&#8217;t be treated badly,” said Minister Buttimer.</p>
<p>The minister spoke to us in the midst of attending a showcase event in Athlone today to celebrate the achievements of community workers nationwide through the Social Inclusion and Community Activation Programme (SICAP).</p>
<blockquote><p><a href="https://changingireland.ie/clare-ppn-co-ordinator-sarah-clancy-abducted-flotilla/">Clare PPN co-ordinator Sarah Clancy abducted sailing to Gaza</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Clare PPN co-ordinator Sarah Clancy abducted sailing to Gaza” — Changing Ireland" src="https://changingireland.ie/clare-ppn-co-ordinator-sarah-clancy-abducted-flotilla/embed/#?secret=HDvF3jv5Sg#?secret=Zq3WagG5CU" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Jerry Buttimer, the Minister of State with responsibility for Community Development and Charities, today addressed the situation that community worker Sarah Clancy and other Irish citizens who have been detained by Israeli authorities while attempting to sail to Gaza find themselves in. He said international law applies to all of us, including Israel, and expressed concern for Sarah and others.', 'https://changingireland.ie/wp-content/uploads/2025/10/Minister-Jerry-Buttimer-at-the-SICAP-In-Our-Words-showcase-in-Athlone-copy-scaled.jpg', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"}]', '[{"slug":"flotilla","title":"Flotilla"},{"slug":"gaza","title":"Gaza"},{"slug":"human-rights","title":"human rights"},{"slug":"minister-jerry-buttimer","title":"Minister Jerry Buttimer"},{"slug":"sarah-clancy","title":"Sarah Clancy"}]', '', 255457, 1, '2025-10-02T16:44:41Z', '2025-10-17T13:11:55Z', '2025-10-02T16:44:41Z')
