INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€20 book on Cork’s years as a healthy city now free online', 'e20-book-on-corks-years-as-a-healthy-city-now-free-online', '<p>The book showcases the projects partnered with or led by Cork Healthy Cities so that other cities and urban spaces across Ireland can learn from Cork’s experience and forge their own path. It records the highs and the lows and the learning along the way.</p>
<p>The book, heralded as the first of its kind published in Ireland or across Europe “highlights this intersectoral approach and showcases the key projects in Cork that have changed the dial to develop Cork as one of Ireland’s most liveable cities”.</p>
<p>An example of one such project is Green Spaces for Health, which started in 2018 coordinated by Maria Young, and has initiated and supports 25 (and counting) projects, especially community gardens. The project has resulted in a some life-changing health impacts for communities.<br />
In terms of encouraging intersectoral policy action, the book welcomed the launch of Sláintecare’s Healthy Communities programme, as a “concerted focus on addressing health inequalities“ in communities in Ireland.</p>
<p>It is a book with a healthy (pardon the pun) mix of text, photos and graphs which makes it easy to move from reading one section to another.<br />
The book was edited by Denise Cahill and Monica O’Mullane and went on sale last year for €20.</p>
<p>You can find out more about the book here: <a href="https://corkhealthycities.com">https://corkhealthycities.com</a> and you are now welcome to download it for free from: <a href="https://bit.ly/CorkHealthyCity">https://bit.ly/CorkHealthyCity</a></p>', 'Last year, a 180-page book titled – ‘Commitment, Collaboration & Continuity: Celebrating Cork as a Healthy City’ was launched to mark the first decade of the city’s involvement in the World Health Organisation’s Healthy Cities initiative. You can now get your hands on it for free.', 'https://changingireland.ie/wp-content/uploads/2025/07/This-book-‘Celebrating-Cork-as-a-Healthy-City-is-now-available-for-free-online.jpg', '', '[{"slug":"health","title":"Health"}]', '[]', '', 255206, 1, '2025-07-20T22:16:24Z', '2025-07-11T16:41:25Z', '2025-07-20T22:16:24Z')
