INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('What would you do if you had a magic wand?', 'wheels-summit-if-i-had-a-magic-wand', '<p>Alexandrina Najmowicz, secretary general of the European Civil Society Forum, replied:</p>
<p>“Well, while people are in competition for rights, for access to basic rights and dignity, this puts our democracy at risk because trust in institutions is at risk.</p>
<p>“What we need is to be able to trust (and) to do that, we need dialogue among us, we need to (talk) with the increasingly polarised communities, and we definitely need to (talk) with institutions so that we can change the current policies.”</p>
<p>Elaine Teague, CEO of the Disability Federation of Ireland, said, “I would bring certainty around funding requirements, because then we can deliver to the people that we support, we can deliver on our commitment to our communities.”</p>
<p>Irish Times journalist Emmet Malone, a guest speaker, said, “I don&#8217;t understand why there are certain elements of the Community and Voluntary sector that are not run by the state.”</p>
<p>He said it was great that small organisations and community groups are flexible, because communities would otherwise be “waiting an endless amount of time for state supports”.</p>
<p>If he had a magic wand he would “divide the sector into stuff that should be run by the state and take that into the state sector and I would properly fund the rest of it over the long term.”</p>
<p>The Wheel&#8217;s summit was held on May 28 in Croke Park, Dublin.</p>', 'Three panellists at The Wheel’s Summit in Croke Park, Dublin, on May 28, were asked what they would do with the community and voluntary sector if they had a magic wand.', 'https://changingireland.ie/wp-content/uploads/2025/07/IMG_0545-scaled.jpg', '', '[{"slug":"initiatives","title":"Initiatives"}]', '[]', '', 255230, 1, '2025-07-11T14:06:39Z', '2025-07-11T16:42:16Z', '2025-07-11T14:06:39Z')
